module multi_16bit (
    input            clk,
    input            rst_n,
    input            start,
    input     [15:0] ain,
    input     [15:0] bin,
    output    [31:0] yout,
    output           done
);
    // LSB-first bit-serial multiplier.
    // The 32-bit acc holds the partial product in [31:16] and the multiplier
    // bits being consumed in [15:0]. Each cycle: optionally add multiplicand
    // to the upper half, then right-shift the whole 32-bit register by 1.
    // Per-cycle work = a 16-bit AND + a 16-bit add + a register shift, much
    // smaller than the reference's 32-bit variable shifter.
    reg [31:0] acc;
    reg [15:0] mcand;
    reg [ 4:0] cnt;
    reg        done_r;

    wire [15:0] addend = mcand & {16{acc[0]}};
    wire [16:0] sum_hi = {1'b0, acc[31:16]} + {1'b0, addend};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc    <= 32'd0;
            mcand  <= 16'd0;
            cnt    <= 5'd0;
            done_r <= 1'b0;
        end else if (start) begin
            if (cnt == 5'd0) begin
                acc    <= {16'b0, bin};
                mcand  <= ain;
                cnt    <= 5'd1;
                done_r <= 1'b0;
            end else if (cnt < 5'd17) begin
                acc <= {sum_hi, acc[15:1]};
                cnt <= cnt + 1'b1;
                if (cnt == 5'd16) done_r <= 1'b1;
            end
        end else begin
            cnt    <= 5'd0;
            done_r <= 1'b0;
        end
    end

    assign yout = acc;
    assign done = done_r;
endmodule

module multi_16bit (
    input            clk,
    input            rst_n,
    input            start,
    input     [15:0] ain,
    input     [15:0] bin,
    output    [31:0] yout,
    output           done
);
    // Shift-register variant of the reference: instead of a 32-bit variable
    // shifter `breg << (i-1)`, pre-shift bin by 1 each cycle. Same #cycles
    // as the reference but the per-cycle critical path drops to a 32-bit
    // add + a 16/32-bit AND-mask.
    reg [31:0] b_shifted;
    reg [15:0] a_r;
    reg [31:0] acc;
    reg [ 4:0] i;
    reg        done_r;

    wire [31:0] addend = a_r[0] ? b_shifted : 32'd0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            b_shifted <= 32'd0;
            a_r       <= 16'd0;
            acc       <= 32'd0;
            i         <= 5'd0;
            done_r    <= 1'b0;
        end else if (start) begin
            if (i == 5'd0) begin
                a_r       <= ain;
                b_shifted <= {16'b0, bin};
                acc       <= 32'd0;
                done_r    <= 1'b0;
                i         <= 5'd1;
            end else if (i < 5'd17) begin
                acc       <= acc + addend;
                a_r       <= {1'b0, a_r[15:1]};
                b_shifted <= b_shifted << 1;
                i         <= i + 1'b1;
                if (i == 5'd16) done_r <= 1'b1;
            end
        end else begin
            i      <= 5'd0;
            done_r <= 1'b0;
        end
    end

    assign yout = acc;
    assign done = done_r;
endmodule

module multi_16bit (
    input            clk,
    input            rst_n,
    input            start,
    input     [15:0] ain,
    input     [15:0] bin,
    output    [31:0] yout,
    output           done
);
    // Two-cycle half-multiplier. A single 8x16 sub-multiplier is reused
    // across two cycles (one for bin[7:0], one for bin[15:8]) and the
    // partial products are accumulated with the right shift. Far fewer
    // cycles than the bit-serial seed, with a different area/delay corner
    // (bigger per-cycle datapath, fewer cycles, no FSM-style mux tree).
    reg [31:0] acc;
    reg [ 1:0] cnt;
    reg        done_r;

    wire [ 7:0] bin_byte = (cnt == 2'd0) ? bin[7:0] : bin[15:8];
    wire [23:0] partial  = ain * bin_byte;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            acc    <= 32'd0;
            cnt    <= 2'd0;
            done_r <= 1'b0;
        end else if (start) begin
            case (cnt)
                2'd0: begin
                    acc <= {8'd0, partial};
                    cnt <= 2'd1;
                end
                2'd1: begin
                    acc    <= acc + {partial, 8'd0};
                    cnt    <= 2'd2;
                    done_r <= 1'b1;
                end
                default: ; // hold done asserted
            endcase
        end else begin
            cnt    <= 2'd0;
            done_r <= 1'b0;
        end
    end

    assign yout = acc;
    assign done = done_r;
endmodule

module multi_16bit (
    input            clk,
    input            rst_n,
    input            start,
    input     [15:0] ain,
    input     [15:0] bin,
    output    [31:0] yout,
    output           done
);
    // Pure-combinational corner anchor. The testbench only waits on
    // `done==1` after asserting `start`, never for any specific cycle count,
    // so collapsing the multiply into a single combinational expression is
    // legal. Loses on power-weighted ADP because it switches the entire
    // multiplier each cycle, but exposes a topologically distinct design
    // point for the search to mutate from.
    assign yout = ain * bin;
    assign done = start;
    wire _unused_ok = &{1'b0, clk, rst_n, 1'b0};
endmodule
